-- =====================================================================
-- Functions (all SECURITY DEFINER; they re-check auth.uid() themselves)
-- =====================================================================

create or replace function public.feature_similarity(a double precision[], b double precision[])
returns integer language sql immutable as $$
  select round((100 * (1 - sqrt((select sum(power(x - y, 2)) from unnest(a, b) as t(x, y))) / sqrt(8)))::numeric)::integer;
$$;

create or replace function public.social_eligible(uid uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.profiles p
                 where p.id = uid and p.username is not null and p.share_results
                   and p.age_confirmed and not p.banned);
$$;

-- Dropped first so re-running this file after a later migration (which changed the return type) works.
drop function if exists public.my_profile();
create or replace function public.my_profile()
returns table (username text, avatar_emoji text, share_results boolean, show_last_seen boolean, age_confirmed boolean, banned boolean)
language sql stable security definer set search_path = public as $$
  select p.username, p.avatar_emoji, p.share_results, p.show_last_seen, p.age_confirmed, p.banned
  from public.profiles p where p.id = auth.uid();
$$;

create or replace function public.save_my_profile(p_username text, p_emoji text, p_share boolean, p_show_last_seen boolean, p_age_confirmed boolean)
returns void language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  if p_username is null or p_username !~ '^[A-Za-z0-9_ء-ي]{3,20}$' then raise exception 'invalid_username'; end if;
  if char_length(coalesce(p_emoji, '')) not between 1 and 8 then raise exception 'invalid_emoji'; end if;
  if p_share and not p_age_confirmed then raise exception 'age_required'; end if;
  insert into public.profiles (id) values (auth.uid()) on conflict (id) do nothing;
  begin
    update public.profiles
       set username = p_username, avatar_emoji = p_emoji, share_results = p_share,
           show_last_seen = p_show_last_seen, age_confirmed = p_age_confirmed
     where id = auth.uid() and not banned;
  exception when unique_violation then
    raise exception 'username_taken';
  end;
  if not p_share then delete from public.shared_features where user_id = auth.uid(); end if;
end;
$$;

create or replace function public.publish_features(vec double precision[])
returns void language plpgsql security definer set search_path = public as $$
declare v double precision;
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  if not public.social_eligible(auth.uid()) then raise exception 'not_eligible'; end if;
  if vec is null or array_length(vec, 1) <> 8 then raise exception 'invalid_features'; end if;
  foreach v in array vec loop
    if v is null or v < 0 or v > 1 then raise exception 'invalid_features'; end if;
  end loop;
  insert into public.shared_features (user_id, features) values (auth.uid(), vec)
  on conflict (user_id) do update set features = excluded.features, updated_at = now();
end;
$$;

drop function if exists public.find_similar(integer, integer);
create or replace function public.find_similar(min_similarity integer default null, lim integer default 50)
returns table (user_id uuid, username text, avatar_emoji text, similarity integer)
language plpgsql stable security definer set search_path = public as $$
declare threshold integer := coalesce(min_similarity, public.setting_int('chat_min_similarity', 70));
begin
  if auth.uid() is null or not public.social_eligible(auth.uid()) then return; end if;
  return query
    select p.id, p.username, p.avatar_emoji, public.feature_similarity(me.features, sf.features) as s
    from public.shared_features me
    join public.shared_features sf on sf.user_id <> me.user_id
    join public.profiles p on p.id = sf.user_id
    where me.user_id = auth.uid()
      and p.username is not null and p.share_results and p.age_confirmed and not p.banned
      and not public.is_blocked(auth.uid(), sf.user_id)
      and public.feature_similarity(me.features, sf.features) >= threshold
    order by s desc, p.username
    limit least(greatest(lim, 1), 100);
end;
$$;

create or replace function public.start_conversation(other uuid)
returns uuid language plpgsql security definer set search_path = public as $$
declare a uuid; b uuid; cid uuid; sim integer;
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  if other is null or other = auth.uid() then raise exception 'invalid_user'; end if;
  if not public.social_eligible(auth.uid()) or not public.social_eligible(other) then raise exception 'not_eligible'; end if;
  if public.is_blocked(auth.uid(), other) then raise exception 'blocked'; end if;
  a := least(auth.uid(), other); b := greatest(auth.uid(), other);
  select id into cid from public.conversations where user_a = a and user_b = b;
  if cid is not null then return cid; end if;
  select public.feature_similarity(m.features, o.features) into sim
    from public.shared_features m, public.shared_features o
   where m.user_id = auth.uid() and o.user_id = other;
  if sim is null or sim < public.setting_int('chat_min_similarity', 70) then raise exception 'not_similar_enough'; end if;
  insert into public.conversations (user_a, user_b) values (a, b)
  on conflict (user_a, user_b) do nothing;
  select id into cid from public.conversations where user_a = a and user_b = b;
  return cid;
end;
$$;

create or replace function public.send_message(conv uuid, text_body text)
returns uuid language plpgsql security definer set search_path = public as $$
declare c public.conversations; other uuid; mid uuid; t text := btrim(coalesce(text_body, ''));
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  select * into c from public.conversations where id = conv and auth.uid() in (user_a, user_b);
  if not found then raise exception 'forbidden'; end if;
  other := case when c.user_a = auth.uid() then c.user_b else c.user_a end;
  if public.is_blocked(auth.uid(), other) then raise exception 'blocked'; end if;
  if exists (select 1 from public.profiles where id = auth.uid() and banned) then raise exception 'banned'; end if;
  if char_length(t) not between 1 and 1000 then raise exception 'invalid_message'; end if;
  if (select count(*) from public.messages where sender_id = auth.uid() and created_at > now() - interval '1 minute') >= 30 then
    raise exception 'rate_limited';
  end if;
  insert into public.messages (conversation_id, sender_id, kind, body) values (conv, auth.uid(), 'text', t) returning id into mid;
  update public.conversations set last_message_at = now() where id = conv;
  return mid;
end;
$$;

create or replace function public.mark_read(conv uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  update public.messages m set read_at = now()
   where m.conversation_id = conv and m.sender_id <> auth.uid() and m.read_at is null
     and exists (select 1 from public.conversations c where c.id = conv and auth.uid() in (c.user_a, c.user_b));
end;
$$;

create or replace function public.touch_presence()
returns void language sql security definer set search_path = public as $$
  update public.profiles set last_seen = now() where id = auth.uid();
$$;

create or replace function public.my_conversations()
returns table (conversation_id uuid, other_id uuid, other_username text, other_emoji text, other_last_seen timestamptz,
               last_body text, last_kind text, last_at timestamptz, unread integer)
language sql stable security definer set search_path = public as $$
  select c.id,
         o.id,
         coalesce(o.username, 'مستخدم'),
         o.avatar_emoji,
         case when o.show_last_seen then o.last_seen else null end,
         lm.body, lm.kind, coalesce(lm.created_at, c.last_message_at),
         (select count(*)::integer from public.messages m
           where m.conversation_id = c.id and m.sender_id <> auth.uid() and m.read_at is null)
  from public.conversations c
  join public.profiles o on o.id = case when c.user_a = auth.uid() then c.user_b else c.user_a end
  left join lateral (select body, kind, created_at from public.messages
                      where conversation_id = c.id order by created_at desc limit 1) lm on true
  where auth.uid() in (c.user_a, c.user_b)
    and not public.is_blocked(auth.uid(), o.id)
  order by coalesce(lm.created_at, c.last_message_at) desc;
$$;

create or replace function public.block_user(target uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  if target is null or target = auth.uid() then raise exception 'invalid_user'; end if;
  insert into public.blocks (blocker_id, blocked_id) values (auth.uid(), target) on conflict do nothing;
end;
$$;

create or replace function public.unblock_user(target uuid)
returns void language sql security definer set search_path = public as $$
  delete from public.blocks where blocker_id = auth.uid() and blocked_id = target;
$$;

create or replace function public.blocked_users()
returns table (user_id uuid, username text)
language sql stable security definer set search_path = public as $$
  select b.blocked_id, coalesce(p.username, 'مستخدم') from public.blocks b
  left join public.profiles p on p.id = b.blocked_id where b.blocker_id = auth.uid();
$$;

create or replace function public.report_user(target uuid, msg uuid, p_reason text)
returns void language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  if target is null or target = auth.uid() then raise exception 'invalid_user'; end if;
  if char_length(btrim(coalesce(p_reason, ''))) not between 1 and 500 then raise exception 'invalid_reason'; end if;
  if (select count(*) from public.abuse_reports where reporter_id = auth.uid() and created_at > now() - interval '1 day') >= 20 then
    raise exception 'rate_limited';
  end if;
  insert into public.abuse_reports (reporter_id, reported_user_id, message_id, reason) values (auth.uid(), target, msg, btrim(p_reason));
end;
$$;

-- ---------- wallet / gifts
create or replace function public.my_wallet()
returns table (coins bigint, rewards bigint, last_daily_claim date)
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  insert into public.wallets (user_id) values (auth.uid()) on conflict (user_id) do nothing;
  return query select w.coins, w.rewards, w.last_daily_claim from public.wallets w where w.user_id = auth.uid();
end;
$$;

create or replace function public.claim_daily_coins()
returns bigint language plpgsql security definer set search_path = public as $$
declare w public.wallets; amount integer := public.setting_int('daily_free_coins', 20);
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  if exists (select 1 from public.profiles where id = auth.uid() and banned) then raise exception 'banned'; end if;
  insert into public.wallets (user_id) values (auth.uid()) on conflict (user_id) do nothing;
  select * into w from public.wallets where user_id = auth.uid() for update;
  if w.last_daily_claim = (now() at time zone 'utc')::date then raise exception 'already_claimed'; end if;
  if amount <= 0 then raise exception 'daily_coins_disabled'; end if;
  update public.wallets set coins = coins + amount, last_daily_claim = (now() at time zone 'utc')::date, updated_at = now()
   where user_id = auth.uid() returning * into w;
  insert into public.coin_ledger (user_id, balance_type, delta, reason) values (auth.uid(), 'coins', amount, 'daily_free');
  return w.coins;
end;
$$;

create or replace function public.send_gift(conv uuid, p_gift uuid, idem text)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  c public.conversations; g public.gifts; other uuid; claimed uuid; mid uuid; existing uuid;
  reward integer; sender_coins bigint; first_id uuid; second_id uuid;
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  if idem is null or char_length(idem) not between 8 and 64 then raise exception 'invalid_idempotency_key'; end if;

  select * into c from public.conversations where id = conv and auth.uid() in (user_a, user_b);
  if not found then raise exception 'forbidden'; end if;
  other := case when c.user_a = auth.uid() then c.user_b else c.user_a end;
  if public.is_blocked(auth.uid(), other) then raise exception 'blocked'; end if;
  if exists (select 1 from public.profiles where id = auth.uid() and banned) then raise exception 'banned'; end if;

  select * into g from public.gifts
   where id = p_gift and active and (starts_at is null or starts_at <= now()) and (ends_at is null or ends_at > now());
  if not found then raise exception 'gift_unavailable'; end if;

  if g.price = 0 and (select count(*) from public.gift_sends
                       where sender_id = auth.uid() and price = 0 and created_at >= (now() at time zone 'utc')::date)
                     >= public.setting_int('free_gift_daily_limit', 5) then
    raise exception 'free_limit_reached';
  end if;

  reward := floor(g.price * public.setting_int('reward_rate_percent', 50) / 100.0)::integer;

  -- idempotency: claim the key first; a duplicate/retried request returns the original result
  insert into public.gift_sends (sender_id, receiver_id, conversation_id, gift_id, price, reward, idempotency_key)
  values (auth.uid(), other, conv, g.id, g.price, reward, idem)
  on conflict (sender_id, idempotency_key) do nothing
  returning id into claimed;
  if claimed is null then
    select message_id into existing from public.gift_sends where sender_id = auth.uid() and idempotency_key = idem;
    return existing;
  end if;

  insert into public.wallets (user_id) values (auth.uid()), (other) on conflict (user_id) do nothing;
  -- lock both wallets in a fixed order to avoid deadlocks
  first_id := least(auth.uid(), other); second_id := greatest(auth.uid(), other);
  perform 1 from public.wallets where user_id = first_id for update;
  perform 1 from public.wallets where user_id = second_id for update;

  if g.price > 0 then
    select coins into sender_coins from public.wallets where user_id = auth.uid();
    if sender_coins < g.price then raise exception 'insufficient_coins'; end if;
    update public.wallets set coins = coins - g.price, updated_at = now() where user_id = auth.uid();
    insert into public.coin_ledger (user_id, balance_type, delta, reason, ref_id) values (auth.uid(), 'coins', -g.price, 'gift_sent', claimed);
    if reward > 0 then
      update public.wallets set rewards = rewards + reward, updated_at = now() where user_id = other;
      insert into public.coin_ledger (user_id, balance_type, delta, reason, ref_id) values (other, 'rewards', reward, 'gift_received', claimed);
    end if;
  end if;

  insert into public.messages (conversation_id, sender_id, kind, body, gift_id) values (conv, auth.uid(), 'gift', '', g.id) returning id into mid;
  update public.gift_sends set message_id = mid where id = claimed;
  update public.conversations set last_message_at = now() where id = conv;
  return mid;
end;
$$;

-- ---------- admin
create or replace function public.admin_list_reports(p_status text default 'open')
returns table (id uuid, reporter text, reported_id uuid, reported text, message_body text, reason text, status text, created_at timestamptz)
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_admin() then raise exception 'forbidden'; end if;
  return query
    select r.id, coalesce(rp.username, 'مستخدم'), r.reported_user_id, coalesce(ru.username, 'مستخدم'),
           m.body, r.reason, r.status, r.created_at
    from public.abuse_reports r
    left join public.profiles rp on rp.id = r.reporter_id
    left join public.profiles ru on ru.id = r.reported_user_id
    left join public.messages m on m.id = r.message_id
    where p_status is null or r.status = p_status
    order by r.created_at desc limit 200;
end;
$$;

create or replace function public.admin_resolve_report(p_id uuid, p_status text)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.is_admin() then raise exception 'forbidden'; end if;
  if p_status not in ('reviewed','dismissed','actioned') then raise exception 'invalid_status'; end if;
  update public.abuse_reports set status = p_status, reviewed_by = auth.uid(), reviewed_at = now() where id = p_id;
end;
$$;

create or replace function public.admin_set_ban(target uuid, p_banned boolean)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.is_admin() then raise exception 'forbidden'; end if;
  update public.profiles set banned = p_banned where id = target;
end;
$$;

create or replace function public.admin_set_setting(k text, v text)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.is_admin() then raise exception 'forbidden'; end if;
  if k not in ('daily_free_coins','free_gift_daily_limit','reward_rate_percent','chat_min_similarity') then raise exception 'unknown_setting'; end if;
  if v !~ '^[0-9]{1,6}$' then raise exception 'invalid_value'; end if;
  if k in ('reward_rate_percent','chat_min_similarity') and v::integer > 100 then raise exception 'invalid_value'; end if;
  insert into public.app_settings (key, value) values (k, v)
  on conflict (key) do update set value = excluded.value, updated_at = now();
end;
$$;

-- grant virtual coins (never real money); recorded in the append-only ledger
create or replace function public.admin_grant_coins(target uuid, amount integer, note text)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.is_admin() then raise exception 'forbidden'; end if;
  if amount = 0 or abs(amount) > 100000 then raise exception 'invalid_amount'; end if;
  insert into public.wallets (user_id) values (target) on conflict (user_id) do nothing;
  perform 1 from public.wallets where user_id = target for update;
  update public.wallets set coins = coins + amount, updated_at = now() where user_id = target; -- CHECK blocks negative balance
  insert into public.coin_ledger (user_id, balance_type, delta, reason) values (target, 'coins', amount, 'admin:' || left(coalesce(note, ''), 100));
end;
$$;

create or replace function public.admin_stats()
returns json language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_admin() then raise exception 'forbidden'; end if;
  return json_build_object(
    'users', (select count(*) from public.profiles),
    'social_users', (select count(*) from public.profiles where share_results),
    'conversations', (select count(*) from public.conversations),
    'messages', (select count(*) from public.messages),
    'gift_sends', (select count(*) from public.gift_sends),
    'coins_spent', (select coalesce(sum(-delta), 0) from public.coin_ledger where balance_type = 'coins' and delta < 0),
    'coins_issued', (select coalesce(sum(delta), 0) from public.coin_ledger where balance_type = 'coins' and delta > 0),
    'open_reports', (select count(*) from public.abuse_reports where status = 'open'));
end;
$$;

create or replace function public.am_i_admin() returns boolean language sql stable security definer set search_path = public as $$
  select public.is_admin();
$$;

-- ---------- execute privileges: authenticated only
do $$
declare f text;
begin
  foreach f in array array[
    'is_admin()', 'setting_int(text,integer)', 'social_eligible(uuid)', 'my_profile()',
    'save_my_profile(text,text,boolean,boolean,boolean)', 'publish_features(double precision[])',
    'find_similar(integer,integer)', 'start_conversation(uuid)', 'send_message(uuid,text)', 'mark_read(uuid)',
    'touch_presence()', 'my_conversations()', 'block_user(uuid)', 'unblock_user(uuid)', 'blocked_users()',
    'report_user(uuid,uuid,text)', 'my_wallet()', 'claim_daily_coins()', 'send_gift(uuid,uuid,text)',
    'admin_list_reports(text)', 'admin_resolve_report(uuid,text)', 'admin_set_ban(uuid,boolean)',
    'admin_set_setting(text,text)', 'admin_grant_coins(uuid,integer,text)', 'admin_stats()', 'am_i_admin()',
    'is_blocked(uuid,uuid)', 'feature_similarity(double precision[],double precision[])'
  ] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;

-- To make yourself an admin (SQL editor, once):
--   insert into public.admin_users (user_id) values ('<your auth.users id>');
-- ############ END 20260102000000_social.sql ############


-- ############ BEGIN 20260103000000_similarity_v2.sql ############
-- Similarity v2 + visibility/chat switches. Run AFTER 20260102000000_social.sql. Safe to re-run.
-- * Similarity is computed over ALL shared tests; each test is weighted by its number of questions
--   (weights come from the server-side catalog below, so a client cannot inflate them).
-- * Sensitive tests (dark traits, attachment) are never shared: they are not in the catalog.
-- * Users can hide themselves from "people like you" and switch chat on/off.

alter table public.profiles
  add column if not exists visible boolean not null default true,
  add column if not exists allow_chat boolean not null default true;

-- ---------- catalog of shareable tests (id, number of dimensions, number of questions)
create table if not exists public.assessment_catalog (
  test_id text primary key,
  dims integer not null check (dims > 0),
  items integer not null check (items > 0)
);
alter table public.assessment_catalog enable row level security; -- no policies: read only inside definer functions
revoke all on public.assessment_catalog from authenticated, anon;
insert into public.assessment_catalog (test_id, dims, items) values
  ('main_mbti', 4, 24),
  ('main_enneagram', 9, 36),
  ('main_arfd', 4, 12),
  ('x_bigfive', 5, 20),
  ('x_hexaco', 6, 18),
  ('x_disc', 4, 16),
  ('x_strengths', 4, 12),
  ('x_workstyle', 6, 18),
  ('x_eq', 4, 12),
  ('x_resilience', 1, 6),
  ('x_locus', 1, 6),
  ('x_cognitive', 4, 12),
  ('x_values', 6, 18),
  ('x_moral', 5, 15),
  ('x_risk', 4, 12),
  ('x_decision', 5, 15),
  ('x_nfc', 1, 6),
  ('x_via', 6, 18),
  ('x_psycap', 4, 12)
on conflict (test_id) do update set dims = excluded.dims, items = excluded.items;

-- ---------- shared score vectors (0..1 per dimension; never raw answers)
create table if not exists public.shared_scores (
  user_id uuid not null references auth.users(id) on delete cascade,
  test_id text not null references public.assessment_catalog(test_id),
  dims double precision[] not null,
  updated_at timestamptz not null default now(),
  primary key (user_id, test_id)
);
create index if not exists idx_shared_scores_test on public.shared_scores(test_id);
alter table public.shared_scores enable row level security;
drop policy if exists shared_scores_own on public.shared_scores;
create policy shared_scores_own on public.shared_scores for select to authenticated using ((select auth.uid()) = user_id);
revoke insert, update, delete on public.shared_scores from authenticated, anon;

create or replace function public.publish_scores_batch(payload jsonb)
returns integer language plpgsql security definer set search_path = public as $$
declare e jsonb; tid text; arr double precision[]; cat record; n integer := 0; v double precision;
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  if not public.social_eligible(auth.uid()) then raise exception 'not_eligible'; end if;
  if payload is null or jsonb_typeof(payload) <> 'array' or jsonb_array_length(payload) > 40 then raise exception 'invalid_payload'; end if;
  for e in select value from jsonb_array_elements(payload) loop
    tid := e->>'test_id';
    select * into cat from public.assessment_catalog where test_id = tid;
    if not found then raise exception 'unknown_test'; end if;
    select array_agg(x::double precision order by o) into arr from jsonb_array_elements_text(e->'dims') with ordinality as t(x, o);
    if arr is null or array_length(arr, 1) <> cat.dims then raise exception 'invalid_scores'; end if;
    foreach v in array arr loop
      if v is null or v < 0 or v > 1 then raise exception 'invalid_scores'; end if;
    end loop;
    insert into public.shared_scores (user_id, test_id, dims) values (auth.uid(), tid, arr)
    on conflict (user_id, test_id) do update set dims = excluded.dims, updated_at = now();
    n := n + 1;
  end loop;
  return n;
end;
$$;

-- Weighted similarity between two users over the tests BOTH shared: sum(questions_t * sim_t) / sum(questions_t).
-- sim_t = 100 * (1 - euclidean_distance / sqrt(number_of_dimensions)). Internal only: NOT granted to clients.
create or replace function public.pair_similarity(a uuid, b uuid)
returns table (similarity integer, tests_used integer, questions_used integer)
language sql stable security definer set search_path = public as $$
  with common as (
    select c.items, x.dims as da, y.dims as db
    from public.shared_scores x
    join public.shared_scores y on y.test_id = x.test_id and y.user_id = b
    join public.assessment_catalog c on c.test_id = x.test_id
    where x.user_id = a
  ), sims as (
    select items,
           100 * (1 - sqrt((select sum(power(u - v, 2)) from unnest(da, db) as t(u, v))) / sqrt(cardinality(da))) as sim
    from common
  )
  select round((sum(items * sim) / sum(items))::numeric)::integer, count(*)::integer, sum(items)::integer from sims;
$$;

-- ---------- profile with the new switches
drop function if exists public.my_profile();
create or replace function public.my_profile()
returns table (username text, avatar_emoji text, share_results boolean, show_last_seen boolean, age_confirmed boolean, banned boolean, visible boolean, allow_chat boolean)
language sql stable security definer set search_path = public as $$
  select p.username, p.avatar_emoji, p.share_results, p.show_last_seen, p.age_confirmed, p.banned, p.visible, p.allow_chat
  from public.profiles p where p.id = auth.uid();
$$;

drop function if exists public.save_my_profile(text, text, boolean, boolean, boolean);
create or replace function public.save_my_profile(
  p_username text, p_emoji text, p_share boolean, p_show_last_seen boolean, p_age_confirmed boolean,
  p_visible boolean default true, p_allow_chat boolean default true)
returns void language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  if p_username is null or p_username !~ '^[A-Za-z0-9_ء-ي]{3,20}$' then raise exception 'invalid_username'; end if;
  if char_length(coalesce(p_emoji, '')) not between 1 and 8 then raise exception 'invalid_emoji'; end if;
  if p_share and not p_age_confirmed then raise exception 'age_required'; end if;
  insert into public.profiles (id) values (auth.uid()) on conflict (id) do nothing;
  begin
    update public.profiles
       set username = p_username, avatar_emoji = p_emoji, share_results = p_share,
           show_last_seen = p_show_last_seen, age_confirmed = p_age_confirmed,
           visible = coalesce(p_visible, true), allow_chat = coalesce(p_allow_chat, true)
     where id = auth.uid() and not banned;
  exception when unique_violation then
    raise exception 'username_taken';
  end;
  if not p_share then
    delete from public.shared_scores where user_id = auth.uid();
    delete from public.shared_features where user_id = auth.uid();
  end if;
end;
$$;

-- ---------- discovery uses the weighted similarity and respects visibility / chat switches
drop function if exists public.find_similar(integer, integer);
create or replace function public.find_similar(min_similarity integer default null, lim integer default 50)
returns table (user_id uuid, username text, avatar_emoji text, similarity integer, tests_used integer, questions_used integer, can_chat boolean)
language plpgsql stable security definer set search_path = public as $$
declare threshold integer := coalesce(min_similarity, public.setting_int('chat_min_similarity', 70));
begin
  if auth.uid() is null or not public.social_eligible(auth.uid()) then return; end if;
  return query
    select p.id, p.username, p.avatar_emoji, s.similarity, s.tests_used, s.questions_used, (p.allow_chat and me.allow_chat)
    from public.profiles me
    join public.profiles p on p.id <> me.id
    cross join lateral public.pair_similarity(me.id, p.id) s
    where me.id = auth.uid()
      and p.username is not null and p.share_results and p.age_confirmed and not p.banned and p.visible
      and s.similarity is not null and s.similarity >= threshold
      and not public.is_blocked(auth.uid(), p.id)
    order by s.similarity desc, p.username
    limit least(greatest(lim, 1), 100);
end;
$$;

create or replace function public.start_conversation(other uuid)
returns uuid language plpgsql security definer set search_path = public as $$
declare a uuid; b uuid; cid uuid; sim integer;
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  if other is null or other = auth.uid() then raise exception 'invalid_user'; end if;
  if not public.social_eligible(auth.uid()) or not public.social_eligible(other) then raise exception 'not_eligible'; end if;
  if public.is_blocked(auth.uid(), other) then raise exception 'blocked'; end if;
  a := least(auth.uid(), other); b := greatest(auth.uid(), other);
  select id into cid from public.conversations where user_a = a and user_b = b;
  if cid is not null then return cid; end if;
  if exists (select 1 from public.profiles where id in (auth.uid(), other) and not allow_chat) then raise exception 'chat_disabled'; end if;
  if not exists (select 1 from public.profiles where id = other and visible) then raise exception 'not_eligible'; end if;
  select s.similarity into sim from public.pair_similarity(auth.uid(), other) s;
  if sim is null or sim < public.setting_int('chat_min_similarity', 70) then raise exception 'not_similar_enough'; end if;
  insert into public.conversations (user_a, user_b) values (a, b) on conflict (user_a, user_b) do nothing;
  select id into cid from public.conversations where user_a = a and user_b = b;
  return cid;
end;
$$;

-- Every message (text or gift) is refused if either side switched chat off.
create or replace function public.messages_chat_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare c public.conversations;
begin
  select * into c from public.conversations where id = new.conversation_id;
  if found and exists (select 1 from public.profiles where id in (c.user_a, c.user_b) and not allow_chat) then
    raise exception 'chat_disabled';
  end if;
  return new;
end;
$$;
drop trigger if exists trg_messages_chat_guard on public.messages;
create trigger trg_messages_chat_guard before insert on public.messages
  for each row execute function public.messages_chat_guard();

-- ---------- execute privileges
do $$
declare f text;
begin
  foreach f in array array[
    'my_profile()', 'save_my_profile(text,text,boolean,boolean,boolean,boolean,boolean)',
    'find_similar(integer,integer)', 'publish_scores_batch(jsonb)', 'start_conversation(uuid)'
  ] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
  revoke all on function public.pair_similarity(uuid, uuid) from public, anon, authenticated;
  revoke all on function public.messages_chat_guard() from public, anon, authenticated;
end $$;
-- ############ END 20260103000000_similarity_v2.sql ############


-- ############ BEGIN 20260104000000_chat_images.sql ############
-- Chat images. Run AFTER 20260103000000_similarity_v2.sql. Safe to re-run.
-- * Private Storage bucket `chat-images`: max 2 MB, only JPEG / PNG / WebP (enforced by Storage).
-- * Path format: <sender uuid>/<conversation uuid>/<uuid>.<jpg|png|webp>
-- * Only participants of the conversation can upload / read (via short-lived signed URLs).
-- * A message is created only by send_image_message(), which re-checks the stored object
--   (exists, size, mime type, owner path), blocks, bans, chat switch and rate limits.
-- Limitation: Storage trusts the declared content-type; the app also verifies the real file signature
--   (magic bytes) before upload, and images are only ever shown through an image decoder.

alter table public.messages drop constraint if exists messages_kind_check;
alter table public.messages add constraint messages_kind_check check (kind in ('text', 'gift', 'image'));

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('chat-images', 'chat-images', false, 2097152, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do update
  set public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

-- ---------- path helpers (policy functions)
create or replace function public.chat_image_path_ok(p_name text)
returns boolean language sql immutable as $$
  select p_name ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(jpg|png|webp)$';
$$;

create or replace function public.chat_image_can_upload(p_name text)
returns boolean language plpgsql stable security definer set search_path = public as $$
declare conv uuid; c public.conversations; other uuid;
begin
  if auth.uid() is null or not public.chat_image_path_ok(p_name) then return false; end if;
  if split_part(p_name, '/', 1) <> auth.uid()::text then return false; end if;
  conv := split_part(p_name, '/', 2)::uuid;
  select * into c from public.conversations where id = conv and auth.uid() in (user_a, user_b);
  if not found then return false; end if;
  other := case when c.user_a = auth.uid() then c.user_b else c.user_a end;
  if public.is_blocked(auth.uid(), other) then return false; end if;
  if exists (select 1 from public.profiles where id in (c.user_a, c.user_b) and (banned or not allow_chat)) then return false; end if;
  if (select count(*) from public.messages where sender_id = auth.uid() and kind = 'image' and created_at > now() - interval '1 hour') >= 20 then
    return false;
  end if;
  return true;
end;
$$;

create or replace function public.chat_image_can_read(p_name text)
returns boolean language plpgsql stable security definer set search_path = public as $$
declare conv uuid;
begin
  if auth.uid() is null or not public.chat_image_path_ok(p_name) then return false; end if;
  conv := split_part(p_name, '/', 2)::uuid;
  return exists (select 1 from public.conversations c where c.id = conv and auth.uid() in (c.user_a, c.user_b));
end;
$$;

drop policy if exists chat_images_insert on storage.objects;
create policy chat_images_insert on storage.objects for insert to authenticated
  with check (bucket_id = 'chat-images' and public.chat_image_can_upload(name));
drop policy if exists chat_images_select on storage.objects;
create policy chat_images_select on storage.objects for select to authenticated
  using (bucket_id = 'chat-images' and public.chat_image_can_read(name));
drop policy if exists chat_images_delete on storage.objects;
create policy chat_images_delete on storage.objects for delete to authenticated
  using (bucket_id = 'chat-images' and split_part(name, '/', 1) = auth.uid()::text);

-- ---------- the only way to create an image message
create or replace function public.send_image_message(conv uuid, p_path text)
returns uuid language plpgsql security definer set search_path = public as $$
declare c public.conversations; other uuid; mid uuid; sz bigint; mt text;
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  select * into c from public.conversations where id = conv and auth.uid() in (user_a, user_b);
  if not found then raise exception 'forbidden'; end if;
  other := case when c.user_a = auth.uid() then c.user_b else c.user_a end;
  if public.is_blocked(auth.uid(), other) then raise exception 'blocked'; end if;
  if exists (select 1 from public.profiles where id = auth.uid() and banned) then raise exception 'banned'; end if;
  if p_path is null or not public.chat_image_path_ok(p_path)
     or split_part(p_path, '/', 1) <> auth.uid()::text or split_part(p_path, '/', 2) <> conv::text then
    raise exception 'invalid_image';
  end if;
  select (o.metadata->>'size')::bigint, o.metadata->>'mimetype' into sz, mt
    from storage.objects o where o.bucket_id = 'chat-images' and o.name = p_path;
  if not found then raise exception 'invalid_image'; end if;
  if sz is null or sz <= 0 or sz > 2097152 or mt not in ('image/jpeg', 'image/png', 'image/webp') then
    raise exception 'invalid_image';
  end if;
  if (select count(*) from public.messages where sender_id = auth.uid() and created_at > now() - interval '1 minute') >= 30 then
    raise exception 'rate_limited';
  end if;
  if (select count(*) from public.messages where sender_id = auth.uid() and kind = 'image' and created_at > now() - interval '1 hour') >= 20 then
    raise exception 'image_limit';
  end if;
  insert into public.messages (conversation_id, sender_id, kind, body) values (conv, auth.uid(), 'image', p_path) returning id into mid;
  update public.conversations set last_message_at = now() where id = conv;
  return mid;
end;
$$;

do $$
declare f text;
begin
  foreach f in array array['chat_image_path_ok(text)', 'chat_image_can_upload(text)', 'chat_image_can_read(text)', 'send_image_message(uuid,text)'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;
-- ############ END 20260104000000_chat_images.sql ############


-- ############ BEGIN 20260105000000_similarity_cache.sql ############
-- Similarity cache. Run AFTER 20260104000000_chat_images.sql. Safe to re-run.
-- Before: find_similar computed the weighted similarity against EVERY user on EVERY call.
-- Now: pair values are stored once and refreshed only when a user's published scores actually change,
--      so find_similar is an indexed read. Stored pairs are those with similarity >= 40
--      (the listing threshold is never lower than 40; admins can still set a higher one).

create table if not exists public.similarity_cache (
  user_a uuid not null references auth.users(id) on delete cascade,
  user_b uuid not null references auth.users(id) on delete cascade,
  similarity integer not null,
  tests_used integer not null,
  questions_used integer not null,
  updated_at timestamptz not null default now(),
  primary key (user_a, user_b),
  check (user_a < user_b)
);
create index if not exists idx_similarity_cache_b on public.similarity_cache(user_b, similarity desc);
alter table public.similarity_cache enable row level security; -- internal table: no policies, no client grants
revoke all on public.similarity_cache from authenticated, anon;

-- Recompute every pair that involves `uid` (called only when its scores changed).
create or replace function public.refresh_similarity_for(uid uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  delete from public.similarity_cache where user_a = uid or user_b = uid;
  insert into public.similarity_cache (user_a, user_b, similarity, tests_used, questions_used)
  select least(uid, o.user_id), greatest(uid, o.user_id), s.similarity, s.tests_used, s.questions_used
  from (select distinct user_id from public.shared_scores where user_id <> uid) o
  cross join lateral public.pair_similarity(uid, o.user_id) s
  where s.similarity is not null and s.similarity >= 40;
end;
$$;

-- When a user stops sharing (their score rows are deleted) their cached pairs disappear too.
create or replace function public.purge_similarity()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  delete from public.similarity_cache where user_a = old.user_id or user_b = old.user_id;
  return old;
end;
$$;
drop trigger if exists trg_purge_similarity on public.shared_scores;
create trigger trg_purge_similarity after delete on public.shared_scores
  for each row execute function public.purge_similarity();

-- Same validation as before, but the cache is refreshed only if something really changed.
create or replace function public.publish_scores_batch(payload jsonb)
returns integer language plpgsql security definer set search_path = public as $$
declare e jsonb; tid text; arr double precision[]; prev double precision[]; cat record; n integer := 0; v double precision; changed boolean := false;
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  if not public.social_eligible(auth.uid()) then raise exception 'not_eligible'; end if;
  if payload is null or jsonb_typeof(payload) <> 'array' or jsonb_array_length(payload) > 40 then raise exception 'invalid_payload'; end if;
  for e in select value from jsonb_array_elements(payload) loop
    tid := e->>'test_id';
    select * into cat from public.assessment_catalog where test_id = tid;
    if not found then raise exception 'unknown_test'; end if;
    select array_agg(x::double precision order by o) into arr from jsonb_array_elements_text(e->'dims') with ordinality as t(x, o);
    if arr is null or array_length(arr, 1) <> cat.dims then raise exception 'invalid_scores'; end if;
    foreach v in array arr loop
      if v is null or v < 0 or v > 1 then raise exception 'invalid_scores'; end if;
    end loop;
    select dims into prev from public.shared_scores where user_id = auth.uid() and test_id = tid;
    if prev is distinct from arr then
      changed := true;
      insert into public.shared_scores (user_id, test_id, dims) values (auth.uid(), tid, arr)
      on conflict (user_id, test_id) do update set dims = excluded.dims, updated_at = now();
    end if;
    n := n + 1;
  end loop;
  if changed then perform public.refresh_similarity_for(auth.uid()); end if;
  return n;
end;
$$;

-- Discovery reads the cache instead of computing similarity against every user.
create or replace function public.find_similar(min_similarity integer default null, lim integer default 50)
returns table (user_id uuid, username text, avatar_emoji text, similarity integer, tests_used integer, questions_used integer, can_chat boolean)
language plpgsql stable security definer set search_path = public as $$
declare threshold integer := greatest(coalesce(min_similarity, public.setting_int('chat_min_similarity', 70)), 40);
begin
  if auth.uid() is null or not public.social_eligible(auth.uid()) then return; end if;
  return query
    with mine as (
      select c.user_b as other, c.similarity, c.tests_used, c.questions_used from public.similarity_cache c where c.user_a = auth.uid()
      union all
      select c.user_a, c.similarity, c.tests_used, c.questions_used from public.similarity_cache c where c.user_b = auth.uid()
    )
    select p.id, p.username, p.avatar_emoji, m.similarity, m.tests_used, m.questions_used, (p.allow_chat and me.allow_chat)
    from mine m
    join public.profiles p on p.id = m.other
    join public.profiles me on me.id = auth.uid()
    where m.similarity >= threshold
      and p.username is not null and p.share_results and p.age_confirmed and not p.banned and p.visible
      and not public.is_blocked(auth.uid(), p.id)
    order by m.similarity desc, p.username
    limit least(greatest(lim, 1), 100);
end;
$$;

-- One-time backfill for users who already shared scores.
do $$
declare u uuid;
begin
  for u in select distinct user_id from public.shared_scores loop
    perform public.refresh_similarity_for(u);
  end loop;
end $$;

revoke all on function public.refresh_similarity_for(uuid) from public, anon, authenticated;
revoke all on function public.purge_similarity() from public, anon, authenticated;
-- ############ END 20260105000000_similarity_cache.sql ############


